namespace ghidra.app.plugin.core.datamgr.actions;






using docking;
using docking.action;
using docking.widgets;
using docking.widgets.tree;
using generic.theme.GThemeDefaults.Colors;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.dtarchive;
using ghidra.util;
using ghidra.util;

public class DeleteArchiveAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	public DeleteArchiveAction(DataTypeManagerPlugin plugin) : base("Delete Archive", plugin.getName())
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(new string[] { "Delete Archive" }, null, "File"));

		setKeyBindingData(new KeyBindingData(KeyEvent.VK_DELETE, 0));

		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths == null || selectionPaths.length != 1) {
			return false;
		}

		DataTypeTreeNode node = (DataTypeTreeNode) selectionPaths[0].getLastPathComponent();
		if (!(node is FileArchiveNode)) {
			return false;
		}
		return ((DataTypeStoreNode) node).isModifiable();
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths == null || selectionPaths.length != 1) {
			return false;
		}

		DataTypeTreeNode node = (DataTypeTreeNode) selectionPaths[0].getLastPathComponent();
		if (!(node is FileArchiveNode)) {
			return false;
		}
		return node is FileArchiveNode;

	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gTree = (GTree) context.getContextObject();
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		FileArchiveNode node = (FileArchiveNode) selectionPaths[0].getLastPathComponent();

		if (OptionDialog.showOptionDialogWithCancelAsDefaultButton(gTree,
			"Confirm Delete Operation",
			"<html><b>Are you sure you want to delete archive: " +
				HTMLUtilities.escapeHTML(node.getName()) + "?<br><br>" + "<font color=\"" +
				Messages.ERROR.toHexString() + "\">(WARNING: This action will permanently " +
				"delete the file from disk.)</font></b>",
			"Yes", OptionDialog.QUESTION_MESSAGE) != OptionDialog.OPTION_ONE) {
			return;
		}

		try {
			FileDataTypeArchive archive = node.getArchive();
			plugin.getArchiveManager().closeArchive(archive);
			archive.delete();
		}
		catch (IOException e1) {
			Msg.showError(this, null, "Error", "Error deleting data type archive.", e1);
		}
	}
}
